const options={navTabs:".nav-tabs a",accorditionTabs:".data.accordition",productInfomationTab:".bls__product-tabs-content",productInfomationTabLayoutSecond:".bls__products-tabs",tabContent:".tab-content .tab-item",tabContentActive:".tab-content .tab-item.active"};var BlsTab={eventProductTabs:function(){document.querySelectorAll(options.navTabs).forEach(t=>{t.addEventListener("click",t=>{t.preventDefault();const e=t.currentTarget,a=e.getAttribute("data-block-id");if(!e.closest(".data.item").classList.contains("active")){for(var o of document.querySelectorAll(".data.item"))o.classList.remove("active");for(var o of document.querySelectorAll(options.tabContent))o.classList.remove("active"),o.querySelector(".tab-panel").style.display="none";const t=document.getElementById(a);t.classList.add("active"),t.querySelector(".tab-panel").style.display="block",e.closest(".data.item").classList.add("active")}},!1)})}};BlsTab.eventProductTabs();